package org.slavicmyths.verify;
import java.util.*;import java.nio.file.*;
import net.minecraft.core.BlockPos;import net.minecraft.world.level.levelgen.Heightmap;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid="slavicmyths") public final class Depth300 {
 @SubscribeEvent public static void start(net.neoforged.neoforge.event.server.ServerStartedEvent e){if(!"depth".equals(System.getProperty("slavicmyths.qa300")))return;try{var w=e.getServer().overworld();var g=w.getChunkSource().getGenerator();var out=new ArrayList<Map<String,Object>>();for(var p:List.of(new BlockPos(4907,36,5540),new BlockPos(4134,23,5553))){w.getChunkAt(p);int noise=g.getBaseHeight(p.getX(),p.getZ(),Heightmap.Types.OCEAN_FLOOR_WG,w,w.getChunkSource().randomState())-1;var col=g.getBaseColumn(p.getX(),p.getZ(),w,w.getChunkSource().randomState());var actual=new LinkedHashMap<Integer,String>();var raw=new LinkedHashMap<Integer,String>();for(int y=45;y<=65;y++){actual.put(y,w.getBlockState(p.atY(y)).toString());raw.put(y,col.getBlock(y).toString());}var plans=new ArrayList<Map<String,Object>>();var chunk=w.getChunkAt(p);for(var entry:chunk.getAllReferences().entrySet())if(entry.getKey() instanceof org.slavicmyths.chud.ChudStructure||entry.getKey() instanceof org.slavicmyths.chud.AbandonedStructure)for(long owner:entry.getValue()){var q=new net.minecraft.world.level.ChunkPos(owner);var start=w.getChunk(q.x,q.z).getStartForStructure(entry.getKey());if(start==null)continue;for(var piece:start.getPieces()){var fills=piece instanceof org.slavicmyths.chud.ChudPiece city?city.blueprint():piece instanceof org.slavicmyths.chud.AbandonedPiece abandoned?abandoned.blueprint():List.<org.slavicmyths.chud.ChudGeometry.Fill>of();int solid=Integer.MIN_VALUE,air=Integer.MIN_VALUE;for(var f:fills){var b=f.box();if(p.getX()<b.minX()||p.getX()>b.maxX()||p.getZ()<b.minZ()||p.getZ()>b.maxZ())continue;if(f.state().isAir())air=Math.max(air,b.maxY());else solid=Math.max(solid,b.maxY());}if(solid!=Integer.MIN_VALUE||air!=Integer.MIN_VALUE)plans.add(Map.of("owner",q.toString(),"max_solid",solid,"max_air_cut",air));}}out.add(Map.of("seed",w.getSeed(),"plans",plans,"point",p.toShortString(),"noise_ground",noise,"actual_ground",org.slavicmyths.worldgen.LandTerrain.ground(w,p.getX(),p.getZ()),"noise_column",raw,"actual_column",actual));}Files.writeString(Path.of("depth300.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));}catch(Exception x){x.printStackTrace();}e.getServer().saveEverything(false,true,true);e.getServer().halt(false);}
}
